    public static EscenarioAsistente Con(
        Func<SolicitudLlm, int, RespuestaLlm> guion,
        IBaseConocimiento? baseConocimiento = null,
        string? canario = null) =>
        new(guion, baseConocimiento ?? new IndiceFijo([], []), canario);

