        Assert.Equal(fragmento, resultado.Respuesta!.Respuesta);
        Assert.Equal(ResultadoAuditoria.Respondida, resultado.Auditoria);
    }

    private const string BaseDelReglamento = "reglamento_academico_2025.md";
